import java.util.*;
import java.io.*;

public class Cutting{

    public static int[] parseLineToIntArray(String line){
        String[] tokens = line.trim().split("\\s+");
        int[] nums = new int[tokens.length];
        for(int i=0; i<tokens.length; i++){
            nums[i] = Integer.parseInt(tokens[i]);
        }
        return nums;
    }

    boolean checkEqualEvenOdd(int[] array, int index){
        int evenCount = 0, oddCount = 0;
        for(int i=0; i<=index; i++){
            if(array[i] % 2 == 0) evenCount++;
            else oddCount++;
        }
        return evenCount == oddCount;
    }

    int findNextCutIndex(int[] array, int coins, Map<Integer,Boolean> used){
        int minIdx = -1;
        int minCost = coins + 1;
        for(int i=1; i<array.length - 1; i++){
            int cost = Math.abs(array[i] - array[i+1]);
            if(cost < minCost && checkEqualEvenOdd(array, i) && !used.containsKey(i)){
                minCost = cost;
                minIdx = i;
            }
        }
        return minIdx;
    }

    public int getMaxNumberOfCuts(int n, int b, int[] a){
        int coinsLeft = b;
        int cutsMade = 0;
        Map<Integer,Boolean> usedIndices = new HashMap<>();
        while(coinsLeft > 0){
            int idx = findNextCutIndex(a, coinsLeft, usedIndices);
            if(idx >= 0){
                usedIndices.put(idx, true);
                int cost = Math.abs(a[idx] - a[idx+1]);
                coinsLeft -= cost;
                cutsMade++;
            } else {
                break;
            }
        }
        return cutsMade;
    }

    public static void main(String[] args) throws Exception{
        Scanner sc = new Scanner(System.in);
        String line1 = sc.nextLine();
        String line2 = sc.nextLine();
        int[] nB = parseLineToIntArray(line1);
        int[] a = parseLineToIntArray(line2);
        Cutting c = new Cutting();
        int n = nB[0];
        int b = nB[1];
        System.out.println(c.getMaxNumberOfCuts(n, b, a));
        sc.close();
    }
}
